import { useEffect, useRef, useState } from "react";
import { THEME_OPTIONS, useTheme } from "../contexts/ThemeContext";
import { toast } from "sonner";
import { BarChart3, Bell, Building2, CalendarClock, Check, ChevronRight, CircleDollarSign, Clock3, Copy, Download, FileCheck2, FileText, History, LayoutDashboard, Link2, LogOut, PenLine, Plus, Save, Search, Settings2, Share2, ShieldCheck, UserCog, UserRound, UsersRound, WalletCards, Wifi, WifiOff, X } from "lucide-react";

type Role = "Admin Master" | "Empregador" | "Trabalhador";
type Worker = { id:string; name:string; phone:string; profession:string; company:string; status:"Ativo"|"Disponível" };
type Company = { id:string; name:string; type:string; owner:string; location:string; employees:number };
type Contract = { id:string; worker:string; company:string; role:string; salary:number; schedule:string; admitted:string; benefits?:string; contractType?:string; status:"Ativo"|"Encerrado"; workerSigned:boolean; employerSigned:boolean; workerSignature?:string; employerSignature?:string; signedAt?:string; terminationReason?:string; terminationDate?:string; closingAmount?:number; workerTerminationSigned?:boolean; employerTerminationSigned?:boolean };
type Account = { id:string; name:string; username:string; role:Role; password:string; active:boolean };
type Payment = { id:string; worker:string; company:string; amount:number; date:string; reference:string; status:"Pago"|"Pendente"; discount:number };
type Punch = { id:string; worker:string; date:string; entry?:string; breakStart?:string; breakEnd?:string; exit?:string };
type Audit = { id:string; action:string; detail:string; when:string; tone:"green"|"gold"|"red" };
type Store = { workers:Worker[]; companies:Company[]; contracts:Contract[]; payments:Payment[]; punches:Punch[]; audits:Audit[]; notifications:number };

const seed:Store={
 workers:[],
 companies:[],
 contracts:[],
 payments:[],
 punches:[],
 audits:[],notifications:0
};
const key="carteira-rpg-store-v1"; const accountsKey="carteira-rpg-accounts-v1";
const defaultAccounts:Account[]=[{id:"ACC-001",name:"Admin Master",username:"master",role:"Admin Master",password:"master123",active:true}];
const encodeLinkData=(value:unknown)=>btoa(unescape(encodeURIComponent(JSON.stringify(value)))).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"");
const decodeLinkData=(value:string)=>{const normalized=value.replace(/-/g,"+").replace(/_/g,"/");const padded=normalized+"=".repeat((4-normalized.length%4)%4);return JSON.parse(decodeURIComponent(escape(atob(padded))))};
const money=(n:number)=>new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL",maximumFractionDigits:0}).format(n);
const blockedDemoTerms=["caio mendes","luna ferreira","ravi costa","bar nebulosa","hospital aurora","oficina valkyria"];const containsBlocked=(value:string)=>{const text=(value||"").trim().toLowerCase();return blockedDemoTerms.some(term=>text.includes(term))};
const sanitizeStore=(value:Store):Store=>{const companies=value.companies.filter(c=>!containsBlocked(`${c.name} ${c.owner}`));const companyNames=new Set(companies.map(c=>c.name));const workers=value.workers.filter(w=>!containsBlocked(`${w.name} ${w.company}`));const workerNames=new Set(workers.map(w=>w.name));return {...value,companies,workers,contracts:value.contracts.filter(c=>workerNames.has(c.worker)&&companyNames.has(c.company)&&!containsBlocked(`${c.worker} ${c.company} ${c.role}`)),payments:value.payments.filter(p=>workerNames.has(p.worker)&&companyNames.has(p.company)&&!containsBlocked(`${p.worker} ${p.company}`)),punches:value.punches.filter(p=>workerNames.has(p.worker)&&!containsBlocked(p.worker)),audits:value.audits.filter(a=>!containsBlocked(`${a.action} ${a.detail}`)),notifications:0}};
const load=():Store=>{try{const v=localStorage.getItem(key);const saved:Store=v?{...seed,...JSON.parse(v) as Partial<Store>}:seed;const cleaned=sanitizeStore(saved);if(JSON.stringify(cleaned)!==JSON.stringify(saved))localStorage.setItem(key,JSON.stringify(cleaned));localStorage.setItem("carteira-rpg-real-data-v4","1");return cleaned}catch{return seed}};
const loadAccounts=():Account[]=>{try{const v=localStorage.getItem(accountsKey);const stored=v?(JSON.parse(v) as Account[]):[];const saved=stored.filter(a=>!containsBlocked(`${a.name} ${a.username}`)&&!(["dante","caio"].includes(a.username.toLowerCase()))).map(a=>a.username.toLowerCase()==="redzin"?{...a,password:"ghostxred52",active:true}:a);const usernames=new Set(saved.map(a=>a.username));const cleaned=[...saved,...defaultAccounts.filter(a=>!usernames.has(a.username))];localStorage.setItem(accountsKey,JSON.stringify(cleaned));return cleaned}catch{return defaultAccounts}};
const now=()=>new Date().toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"});
const today=()=>new Date().toLocaleDateString("pt-BR");
const isoDate=(value:string)=>{if(!value)return today();if(value.includes("/"))return value;return new Date(`${value}T12:00:00`).toLocaleDateString("pt-BR")};
const safeId=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`;
const hoursFor=(p:Punch)=>{if(!p.entry||!p.exit)return 0;const parse=(s:string)=>{const [h,m]=s.split(":").map(Number);return h*60+m};let end=parse(p.exit),start=parse(p.entry);if(end<start)end+=1440;let minutes=end-start;if(p.breakStart&&p.breakEnd)minutes-=Math.max(0,parse(p.breakEnd)-parse(p.breakStart));return Math.max(0,minutes/60)};
const esc=(value:string)=>value.replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[c]||c));

function Badge({children,tone="neutral"}:{children:React.ReactNode;tone?:"green"|"gold"|"red"|"neutral"}){return <span className={`badge ${tone}`}>{children}</span>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="field"><span>{label}</span>{children}</label>}
function SectionTitle({eyebrow,title,action}:{eyebrow:string;title:string;action?:React.ReactNode}){return <div className="section-head"><div><div className="eyebrow">{eyebrow}</div><h2>{title}</h2></div>{action}</div>}

function ContractSigningScreen({payload}:{payload:Contract&{employer:string;employerId?:string}}){const canvasRef=useRef<HTMLCanvasElement|null>(null);const [drawing,setDrawing]=useState(false);const [signature,setSignature]=useState(payload.workerSignature||"");const [saved,setSaved]=useState(Boolean(payload.workerSignature));const start=(e:React.PointerEvent<HTMLCanvasElement>)=>{const canvas=canvasRef.current;if(!canvas)return;canvas.setPointerCapture(e.pointerId);const r=canvas.getBoundingClientRect(),ctx=canvas.getContext("2d");if(!ctx)return;ctx.beginPath();ctx.moveTo((e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height);setDrawing(true)};const move=(e:React.PointerEvent<HTMLCanvasElement>)=>{if(!drawing)return;const canvas=canvasRef.current;if(!canvas)return;const r=canvas.getBoundingClientRect(),ctx=canvas.getContext("2d");if(!ctx)return;ctx.lineWidth=3;ctx.lineCap="round";ctx.strokeStyle="#172033";ctx.lineTo((e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height);ctx.stroke()};const finish=()=>{if(!drawing)return;setDrawing(false);const data=canvasRef.current?.toDataURL("image/png");if(data)setSignature(data)};const save=()=>{if(!signature)return toast.error("Desenhe sua assinatura antes de salvar");const signed={...payload,workerSignature:signature,workerSigned:true,signedAt:new Date().toISOString()};const token=encodeLinkData(signed);localStorage.setItem(`carteira-rpg-assinatura-${payload.id}`,JSON.stringify(signed));setSaved(true);const url=`${location.origin}${location.pathname}?signedContract=${token}`;navigator.clipboard?.writeText(url);toast.success("Contrato assinado e link copiado")};return <div className="login-screen contract-sign-screen"><div className="modal contract-sign-card"><div className="eyebrow">carteira de trabalho • assinatura</div><h1>Contrato {payload.id}</h1><p>Revise os termos abaixo e assine com a caneta. O responsável receberá o documento assinado por este link.</p><div className="document-preview"><h2>CONTRATO DE TRABALHO — RPG</h2><p><b>Empregador:</b> {payload.employer} • <b>Empresa:</b> {payload.company}</p><p><b>Trabalhador:</b> {payload.worker}</p><p><b>Cargo:</b> {payload.role} • <b>Salário:</b> {money(payload.salary)}</p><p><b>Jornada:</b> {payload.schedule} • <b>Admissão:</b> {payload.admitted}</p><p><b>Tipo:</b> {payload.contractType||"Prazo indeterminado"} • <b>Benefícios:</b> {payload.benefits||"Não informado"}</p><hr/><p>O trabalhador cumprirá os horários, respeitará as regras da empresa e exercerá suas funções com responsabilidade. O empregador realizará os pagamentos e manterá os registros de jornada conforme as regras do servidor RPG.</p>{payload.workerSignature&&<p className="signed-document">✓ Assinado pelo trabalhador</p>}</div><label className="signature-label">Assine no quadro abaixo</label><canvas ref={canvasRef} width={760} height={220} className="signature-canvas" onPointerDown={start} onPointerMove={move} onPointerUp={finish} onPointerLeave={finish}/><div className="signature-actions"><button className="ghost" onClick={()=>{const c=canvasRef.current?.getContext("2d");if(c){c.clearRect(0,0,760,220);setSignature("");setSaved(false)}}}>limpar</button><button className="primary" onClick={save}><Save size={16}/> {saved?"salvo":"salvar assinatura"}</button></div>{saved&&<div className="notice"><Share2 size={17}/><div><b>Documento assinado</b><span>O link do documento assinado foi copiado. Você pode enviar pelo WhatsApp ou Telegram.</span></div></div>}</div></div>}
function ThemePicker(){const {theme,setTheme}=useTheme();return <section className="theme-picker panel"><div className="section-head"><div><div className="eyebrow">personalização visual</div><h2>Temas da carteira</h2></div><span className="theme-current">{THEME_OPTIONS.find(option=>option.id===theme)?.label}</span></div><div className="theme-options">{THEME_OPTIONS.map(option=><button type="button" key={option.id} className={`theme-option ${theme===option.id?"selected":""}`} onClick={()=>setTheme(option.id)}><span className={`theme-swatch theme-${option.id}`}><span/></span><span><b>{option.label}</b><small>{option.description}</small></span>{theme===option.id&&<Check size={15}/>}</button>)}</div></section>}

function LoginScreen({accounts,onLogin}:{accounts:Account[];onLogin:(account:Account)=>void}){const [username,setUsername]=useState("");const [password,setPassword]=useState("");const [error,setError]=useState("");const submit=(e:React.FormEvent)=>{e.preventDefault();const a=accounts.find(x=>x.active&&x.username===username.trim()&&x.password===password);if(a)onLogin(a);else setError("Usuário ou senha inválidos")};return <div className="login-screen"><div className="login-card"><div className="brand login-brand"><div className="brand-mark">//</div><div><strong>CARTEIRA</strong><span>DIGITAL RPG</span></div></div><div className="eyebrow">acesso ao servidor</div><h1>Entrar na carteira</h1><p>Use sua conta de trabalho para acessar contratos, ponto e pagamentos.</p><form onSubmit={submit}><Field label="Usuário"><input autoFocus value={username} onChange={e=>setUsername(e.target.value)} placeholder="seu.username"/></Field><Field label="Senha"><input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="••••••••"/></Field>{error&&<div className="login-error">{error}</div>}<button className="primary login-submit">entrar <ChevronRight size={16}/></button></form></div></div>}

function Workspace(){
 const [data,setData]=useState<Store>(load);const [tab,setTab]=useState(()=>new URLSearchParams(window.location.search).get("tab")||"dashboard");const [query,setQuery]=useState("");const [online,setOnline]=useState(false);const [showAdd,setShowAdd]=useState(false);const [showNotifications,setShowNotifications]=useState(false);const [accounts,setAccounts]=useState<Account[]>(loadAccounts);const [session,setSession]=useState<Account|null>(()=>{try{const id=localStorage.getItem("carteira-rpg-session");return loadAccounts().find(a=>a.id===id)||null}catch{return null}});const [workerForm,setWorkerForm]=useState({name:"",id:"",phone:"",profession:"",username:"",password:"",passwordConfirm:""});const [companyForm,setCompanyForm]=useState({name:"",type:"Bar",owner:"",location:""});const [contractForm,setContractForm]=useState({worker:"",company:"",role:"",salary:"",schedule:"",admitted:"",benefits:"",contractType:"Prazo indeterminado"});const [selectedPunchWorker,setSelectedPunchWorker]=useState("");const socketRef=useRef<WebSocket|null>(null);const syncingRef=useRef(false);
 useEffect(()=>{localStorage.setItem(key,JSON.stringify(data));if(!syncingRef.current&&socketRef.current?.readyState===WebSocket.OPEN)socketRef.current.send(JSON.stringify({type:"store-sync",payload:data}));syncingRef.current=false},[data]);
 useEffect(()=>{localStorage.setItem(accountsKey,JSON.stringify(accounts))},[accounts]);
 useEffect(()=>{const proto=location.protocol==="https:"?"wss":"ws";let stopped=false;let timer:ReturnType<typeof setTimeout>|undefined;let attempts=0;const connect=()=>{if(stopped)return;try{const ws=new WebSocket(`${proto}://${location.host}/ws`);socketRef.current=ws;ws.onopen=()=>{attempts=0;setOnline(true)};ws.onclose=()=>{setOnline(false);if(!stopped){timer=setTimeout(connect,Math.min(1000*2**attempts,15000));attempts++}};ws.onerror=()=>ws.close();ws.onmessage=e=>{try{const m=JSON.parse(e.data);if(m.type==="store-sync"&&m.payload){syncingRef.current=true;setData({...seed,...m.payload});toast.info("Dados atualizados por outro operador")}}catch{}}}catch{timer=setTimeout(connect,Math.min(1000*2**attempts,15000));attempts++}};connect();return()=>{stopped=true;if(timer)clearTimeout(timer);socketRef.current?.close()}},[]);
 const filteredWorkers= data.workers.filter(w=>[w.name,w.id,w.profession,w.company].join(" ").toLowerCase().includes(query.toLowerCase()));
 useEffect(()=>{if(!session)return;const signedToken=new URLSearchParams(window.location.search).get("signedContract");if(!signedToken)return;try{const signed=decodeLinkData(signedToken) as Contract;setData(d=>{const exists=d.contracts.some(c=>c.id===signed.id);if(!exists)return d;return {...d,notifications:d.notifications+1,contracts:d.contracts.map(c=>c.id===signed.id?{...c,workerSigned:true,workerSignature:signed.workerSignature,signedAt:signed.signedAt}:c),audits:[{id:safeId(),action:"Contrato assinado recebido",detail:`${signed.id} • ${signed.worker}`,when:"agora",tone:"green"},...d.audits]}});toast.success("Contrato assinado recebido na carteira");window.history.replaceState({},"",window.location.pathname)}catch{toast.error("Não foi possível receber este contrato assinado")}},[session?.id]);
 if(!session)return <LoginScreen accounts={accounts} onLogin={a=>{setSession(a);localStorage.setItem("carteira-rpg-session",a.id);toast.success(`Bem-vindo, ${a.name}`)}}/>;
 const isAdmin=session.role==="Admin Master";const isEmployer=session.role==="Empregador";const isWorker=session.role==="Trabalhador";const myContracts=data.contracts.filter(c=>c.worker===session.name);const canManage=isAdmin||isEmployer;const visibleContracts=isWorker?myContracts:data.contracts;const signedContracts=visibleContracts.filter(c=>c.workerSigned);const activeContracts=data.contracts.filter(c=>c.status==="Ativo");const pending=data.payments.filter(p=>p.status==="Pendente").reduce((s,p)=>s+p.amount,0);const totalPaid=data.payments.filter(p=>p.status==="Pago").reduce((s,p)=>s+p.amount-p.discount,0);const totalHours=data.punches.reduce((s,p)=>s+hoursFor(p),0);const pushAudit=(action:string,detail:string,tone:Audit["tone"]="green")=>setData(d=>({...d,notifications:d.notifications+1,audits:[{id:safeId(),action,detail,when:"agora",tone},...d.audits]}));
 const openAdd=()=>{if(!canManage)return toast.error("Somente admin master e empregador podem cadastrar registros");setContractForm({worker:data.workers[0]?.name||"",company:data.companies[0]?.name||"",role:"",salary:"",schedule:"",admitted:"",benefits:"",contractType:"Prazo indeterminado"});setShowAdd(true)};
 const addWorker=()=>{const name=workerForm.name.trim(),id=workerForm.id.trim(),username=workerForm.username.trim().toLowerCase(),password=workerForm.password; if(!name||!id||!workerForm.profession.trim()||!username||!password)return toast.error("Preencha trabalhador, profissão, usuário e senha");if(password.length<4)return toast.error("A senha deve ter pelo menos 4 caracteres");if(password!==workerForm.passwordConfirm)return toast.error("A confirmação da senha não confere");if(data.workers.some(w=>w.id.toLowerCase()===id.toLowerCase()))return toast.error("Este ID já está cadastrado");if(accounts.some(a=>a.username.toLowerCase()===username))return toast.error("Este usuário já está cadastrado");const worker={name,id,phone:workerForm.phone.trim(),profession:workerForm.profession.trim(),company:"Sem vínculo",status:"Disponível" as const};const account:Account={id:`ACC-${Date.now()}`,name,username,role:"Trabalhador",password,active:true};setData(d=>({...d,workers:[...d.workers,worker]}));setAccounts(list=>[...list,account]);pushAudit("Trabalhador cadastrado",`${worker.name} • ${worker.id}`);pushAudit("Acesso de trabalhador criado",`${account.name} • @${account.username}`);setWorkerForm({name:"",id:"",phone:"",profession:"",username:"",password:"",passwordConfirm:""});setShowAdd(false);toast.success("Trabalhador e acesso criados")};
 const addCompany=()=>{if(!companyForm.name.trim()||!companyForm.owner.trim())return toast.error("Informe o nome e o responsável");const company={...companyForm,id:`EMP-${String(data.companies.length+1).padStart(3,"0")}`,employees:0,name:companyForm.name.trim()};setData(d=>({...d,companies:[...d.companies,company]}));pushAudit("Empresa cadastrada",`${company.name} • ${company.type}`);setCompanyForm({name:"",type:"Bar",owner:"",location:""});setShowAdd(false);toast.success("Empresa cadastrada")};
 const addContract=()=>{const salary=Number(contractForm.salary);if(!contractForm.worker||!contractForm.company||!contractForm.role.trim()||!salary||salary<0)return toast.error("Preencha trabalhador, empresa, cargo e salário válido");const c:Contract={id:`CTR-${1044+data.contracts.length}`,worker:contractForm.worker,company:contractForm.company,role:contractForm.role.trim(),salary,schedule:contractForm.schedule||"A combinar",admitted:isoDate(contractForm.admitted),benefits:contractForm.benefits.trim()||"Não informado",contractType:contractForm.contractType||"Prazo indeterminado",status:"Ativo",workerSigned:false,employerSigned:false};setData(d=>({...d,contracts:[c,...d.contracts],workers:d.workers.map(w=>w.name===c.worker?{...w,company:c.company,status:"Ativo"}:w)}));pushAudit("Novo contrato criado",`${c.worker} • ${c.company}`,"gold");setShowAdd(false);toast.success("Contrato criado e enviado para assinatura")};
 const signContract=(c:Contract)=>{if(isWorker&&c.worker!==session.name)return toast.error("Você só pode assinar seus próprios contratos");if(isEmployer&&!data.companies.some(x=>x.name===c.company&&x.owner===session.name)&&!isAdmin)return toast.error("Você só pode assinar contratos da sua empresa");setData(d=>({...d,contracts:d.contracts.map(x=>x.id===c.id?{...x,workerSigned:x.workerSigned||isWorker,employerSigned:x.employerSigned||!isWorker}:x)}));pushAudit("Contrato assinado",`${c.id} • ${session.name}`);toast.success("Assinatura registrada")};
 const editContract=(c:Contract)=>{if(!canManage)return toast.error("Sem permissão para editar contratos");const role=window.prompt("Novo cargo:",c.role);if(role===null)return;const salaryText=window.prompt("Novo salário mensal (R$):",String(c.salary));if(salaryText===null)return;const salary=Number(salaryText);if(!role.trim()||!salary||salary<0)return toast.error("Cargo e salário válidos são obrigatórios");setData(d=>({...d,contracts:d.contracts.map(x=>x.id===c.id?{...x,role:role.trim(),salary}:x)}));pushAudit("Contrato alterado",`${c.id} • ${role.trim()} • ${money(salary)}`,"gold");toast.success("Cargo e salário atualizados")};
 const closeContract=(c:Contract)=>{if(!canManage)return toast.error("Sem permissão para encerrar vínculos");const reason=window.prompt("Motivo do encerramento:","Encerramento acordado");if(!reason?.trim())return;const amount=Math.round(c.salary/30*10);setData(d=>({...d,contracts:d.contracts.map(x=>x.id===c.id?{...x,status:"Encerrado",terminationReason:reason.trim(),terminationDate:today(),closingAmount:amount,employerTerminationSigned:isEmployer||isAdmin,workerTerminationSigned:x.workerTerminationSigned}:x),workers:d.workers.map(w=>w.name===c.worker&&!d.contracts.some(x=>x.id!==c.id&&x.worker===c.worker&&x.status==="Ativo")?{...w,company:"Sem vínculo",status:"Disponível"}:w)}));pushAudit("Vínculo encerrado",`${c.worker} • ${reason.trim()} • encerramento ${money(amount)}`,"red");toast.success(`Encerramento calculado: ${money(amount)} — assinatura do trabalhador pendente`)};
 const signTermination=(c:Contract)=>{if(c.status!=="Encerrado")return;if(isWorker&&c.worker!==session.name)return toast.error("Você só pode assinar seus encerramentos");if(isEmployer&&!isAdmin)return toast.error("Somente o empregador responsável ou admin pode assinar");setData(d=>({...d,contracts:d.contracts.map(x=>x.id===c.id?{...x,workerTerminationSigned:x.workerTerminationSigned||isWorker,employerTerminationSigned:x.employerTerminationSigned||!isWorker}:x)}));pushAudit("Encerramento assinado",`${c.id} • ${session.name}`);toast.success("Assinatura do encerramento registrada")};
 const registerPayment=(p:Payment)=>{if(!canManage)return toast.error("Somente admin e empregador podem pagar salários");setData(d=>({...d,payments:d.payments.map(x=>x.id===p.id?{...x,status:"Pago",date:today()}:x)}));pushAudit("Pagamento registrado",`${p.worker} • líquido ${money(p.amount-p.discount)}`);toast.success("Pagamento registrado")};
 const createPayment=(c:Contract)=>{if(!canManage)return toast.error("Sem permissão para gerar folha");const reference=window.prompt("Competência do pagamento:","Outubro/2026");if(!reference)return;const discountText=window.prompt("Desconto (R$):","0");if(discountText===null)return;const discount=Math.max(0,Number(discountText)||0);const p:Payment={id:`PAY-${Date.now()}`,worker:c.worker,company:c.company,amount:c.salary,date:"—",reference, status:"Pendente",discount};setData(d=>({...d,payments:[p,...d.payments]}));pushAudit("Pagamento pendente criado",`${p.worker} • ${p.reference} • líquido ${money(p.amount-discount)}`,"gold");toast.success("Pagamento pendente criado")};
 const recordPunch=(worker=session.name)=>{if(!worker)return;const current=data.punches.find(p=>p.worker===worker&&p.date==="Hoje"&&!p.exit);if(!isAdmin&&!isEmployer&&worker!==session.name)return toast.error("Você só pode registrar o próprio ponto");if(!current){setData(d=>({...d,punches:[{id:safeId(),worker,date:"Hoje",entry:now()},...d.punches]}));pushAudit("Entrada registrada",`${worker} • hoje`);return}const patch:Partial<Punch>=!current.breakStart?{breakStart:now()}:!current.breakEnd?{breakEnd:now()}: {exit:now()};setData(d=>({...d,punches:d.punches.map(p=>p.id===current.id?{...p,...patch}:p)}));pushAudit(patch.breakStart?"Intervalo iniciado":patch.breakEnd?"Intervalo encerrado":"Saída registrada",`${worker} • ${now()}`)};
 const deleteAccount=(account:Account)=>{if(!isAdmin||account.username==="master")return toast.error("O Admin Master não pode ser removido");if(!window.confirm(`Excluir o usuário ${account.name}?`))return;setAccounts(list=>list.filter(a=>a.id!==account.id));pushAudit("Usuário excluído",`${account.name} • ${account.username}`,"red");toast.success("Usuário excluído")}; const deleteWorker=(worker:Worker)=>{if(!isAdmin)return toast.error("Apenas o Admin Master pode excluir registros");if(!window.confirm(`Excluir ${worker.name}? O histórico de auditoria será preservado.`))return;setData(d=>({...d,workers:d.workers.filter(w=>w.id!==worker.id),contracts:d.contracts.filter(c=>c.worker!==worker.name),payments:d.payments.filter(p=>p.worker!==worker.name),punches:d.punches.filter(p=>p.worker!==worker.name)}));pushAudit("Trabalhador excluído",`${worker.name} • ${worker.id}`,"red");toast.success("Trabalhador excluído")}; const deleteCompany=(company:Company)=>{if(!isAdmin)return toast.error("Apenas o Admin Master pode excluir registros");if(!window.confirm(`Excluir a empresa ${company.name}?`))return;setData(d=>({...d,companies:d.companies.filter(c=>c.id!==company.id),workers:d.workers.map(w=>w.company===company.name?{...w,company:"Sem vínculo",status:"Disponível"}:w)}));pushAudit("Empresa excluída",`${company.name} • histórico preservado`,"red");toast.success("Empresa excluída")}; const deleteContract=(contract:Contract)=>{if(!isAdmin)return toast.error("Apenas o Admin Master pode excluir registros");if(!window.confirm(`Excluir o contrato ${contract.id}?`))return;setData(d=>({...d,contracts:d.contracts.filter(c=>c.id!==contract.id)}));pushAudit("Contrato excluído",`${contract.id} • ${contract.worker}`,"red");toast.success("Contrato excluído")}; const deletePayment=(payment:Payment)=>{if(!isAdmin)return toast.error("Apenas o Admin Master pode excluir registros");if(!window.confirm(`Excluir o pagamento ${payment.id}?`))return;setData(d=>({...d,payments:d.payments.filter(p=>p.id!==payment.id)}));pushAudit("Pagamento excluído",`${payment.id} • ${payment.worker}`,"red");toast.success("Pagamento excluído")}; const deletePunch=(punch:Punch)=>{if(!isAdmin)return toast.error("Apenas o Admin Master pode excluir registros");if(!window.confirm(`Excluir o registro de ponto de ${punch.worker}?`))return;setData(d=>({...d,punches:d.punches.filter(p=>p.id!==punch.id)}));pushAudit("Registro de ponto excluído",`${punch.worker} • ${punch.date}`,"red");toast.success("Registro de ponto excluído")}; const exportBackup=()=>{const blob=new Blob([JSON.stringify({version:2,exportedAt:new Date().toISOString(),data,accounts},null,2)],{type:"application/json"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=`carteira-rpg-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url);toast.success("Backup JSON exportado")};
 const printReport=(title:string,body:string)=>{const win=window.open("","_blank","width=980,height=700");if(!win)return toast.error("Permita pop-ups para gerar o PDF");win.document.write(`<html><head><title>${esc(title)}</title><style>body{font-family:Arial,sans-serif;color:#111;padding:32px}h1{color:#172342;border-bottom:3px solid #39b6d8;padding-bottom:12px}table{border-collapse:collapse;width:100%;margin-top:20px}th,td{border:1px solid #ccd3df;padding:9px;text-align:left;font-size:12px}th{background:#edf3f8}small{color:#667085}.meta{color:#667085;margin-bottom:24px}</style></head><body><h1>${esc(title)}</h1><div class="meta">Carteira Digital RPG • gerado em ${today()} às ${now()}</div>${body}</body></html>`);win.document.close();win.focus();win.print()};
 const reportWorkers=()=>printReport("Relatório de funcionários",`<table><tr><th>Nome</th><th>ID</th><th>Telefone</th><th>Profissão</th><th>Empresa</th><th>Status</th></tr>${data.workers.map(w=>`<tr><td>${esc(w.name)}</td><td>${esc(w.id)}</td><td>${esc(w.phone)}</td><td>${esc(w.profession)}</td><td>${esc(w.company)}</td><td>${esc(w.status)}</td></tr>`).join("")}</table>`);
 const reportPayroll=()=>printReport("Relatório de salários e despesas",`<table><tr><th>Trabalhador</th><th>Empresa</th><th>Referência</th><th>Bruto</th><th>Desconto</th><th>Líquido</th><th>Status</th><th>Data</th></tr>${data.payments.map(p=>`<tr><td>${esc(p.worker)}</td><td>${esc(p.company)}</td><td>${esc(p.reference)}</td><td>${money(p.amount)}</td><td>${money(p.discount)}</td><td>${money(p.amount-p.discount)}</td><td>${p.status}</td><td>${esc(p.date)}</td></tr>`).join("")}</table><p><b>Total pago:</b> ${money(totalPaid)} &nbsp; <b>Pendente:</b> ${money(pending)}</p>`);
 const reportHours=()=>printReport("Relatório de horas trabalhadas",`<table><tr><th>Trabalhador</th><th>Data</th><th>Entrada</th><th>Intervalo</th><th>Saída</th><th>Horas</th></tr>${data.punches.map(p=>`<tr><td>${esc(p.worker)}</td><td>${esc(p.date)}</td><td>${p.entry||"—"}</td><td>${p.breakStart||"—"} → ${p.breakEnd||"—"}</td><td>${p.exit||"em aberto"}</td><td>${hoursFor(p).toFixed(2)}h</td></tr>`).join("")}</table><p><b>Total registrado:</b> ${totalHours.toFixed(2)} horas</p>`);
 const shareContract=(c:Contract)=>{if(!isAdmin&&!isEmployer)return toast.error("Somente o responsável pode criar o link");const company=data.companies.find(x=>x.name===c.company);const payload={...c,employer:company?.owner||session.name,employerId:session.id};const url=`${location.origin}${location.pathname}?signContract=${encodeLinkData(payload)}`;const text=`Olá ${c.worker}, assine seu contrato ${c.id}: ${url}`;navigator.clipboard?.writeText(url);if(navigator.share){navigator.share({title:`Contrato ${c.id}`,text,url}).catch(()=>{});}else{const whatsapp=`https://wa.me/?text=${encodeURIComponent(text)}`;window.open(whatsapp,"_blank","noopener,noreferrer");}toast.success("Link de assinatura copiado. Escolha WhatsApp, Telegram ou outro app para enviar")};
 const nav=[{id:"dashboard",label:"Painel",icon:LayoutDashboard},{id:"workers",label:"Trabalhadores",icon:UsersRound},{id:"companies",label:"Empresas",icon:Building2},{id:"contracts",label:"Contratos",icon:FileText},{id:"signed",label:"Assinados",icon:FileCheck2},{id:"time",label:"Controle de ponto",icon:Clock3},{id:"payroll",label:"Salários",icon:WalletCards},{id:"reports",label:"Relatórios",icon:BarChart3}];
 return <div className="app-shell"><aside className="sidebar"><div className="brand"><div className="brand-mark">//</div><div><strong>CARTEIRA</strong><span>DIGITAL RPG</span></div></div><div className="workspace"><span className="online-dot"/> servidor RP • produção</div><nav>{nav.map(n=><button key={n.id} className={tab===n.id?"active":""} onClick={()=>setTab(n.id)}><n.icon size={17}/><span>{n.label}</span>{n.id==="dashboard"&&data.notifications>0&&<i>{data.notifications}</i>}</button>)}</nav><div className="sidebar-bottom">{isAdmin&&<button onClick={()=>setTab("settings")}><Settings2 size={17}/> Configurações</button>}<div className="user-chip" role="button" tabIndex={0} onClick={()=>setTab("profile")} onKeyDown={e=>{if(e.key==="Enter")setTab("profile")}} title="Abrir meu perfil"><div className="avatar">{session.name.split(" ").map(x=>x[0]).slice(0,2).join("")}</div><div><b>{session.name}</b><small>{session.role}</small></div><button className="logout-button" title="Sair" onClick={e=>{e.stopPropagation();setSession(null);localStorage.removeItem("carteira-rpg-session")}}><LogOut size={15}/></button></div></div></aside><main className="main"><header className="topbar"><div className="mobile-brand"><span>CARTEIRA</span><b>// RP</b></div><div className="connection">{online?<><Wifi size={14}/> websocket conectado</>:<><WifiOff size={14}/> modo local</>}</div><div className="top-actions"><div className={`notification-wrap ${showNotifications?"is-open":""}`}><button className="icon-button" onClick={()=>{setShowNotifications(v=>!v);if(data.notifications)setData(d=>({...d,notifications:0}))}} aria-label="Abrir notificações"><Bell size={18}/>{data.notifications>0&&<i>{data.notifications}</i>}</button>{showNotifications&&<div className="notification-panel"><div className="notification-head"><b>Notificações</b><button className="ghost" onClick={()=>setShowNotifications(false)}><X size={14}/></button></div>{data.audits.slice(0,8).map(a=><div className="notification-item" key={a.id}><div className={`activity-mark ${a.tone}`}><Bell size={13}/></div><div><b>{a.action}</b><span>{a.detail}</span></div><time>{a.when}</time></div>)}{!data.audits.length&&<span className="empty-form">Nenhuma notificação.</span>}</div>}</div><button className="role-pill" onClick={()=>setTab("profile")} title="Abrir meu perfil"><UserCog size={14}/> {session.role}</button><button className="icon-button" title="Sair" onClick={()=>{setSession(null);localStorage.removeItem("carteira-rpg-session")}}><LogOut size={17}/></button></div></header><div className="mobile-nav">{nav.map(n=><button key={n.id} className={tab===n.id?"active":""} onClick={()=>setTab(n.id)}>{n.label}</button>)}</div><div className="content">
 {tab==="profile"&&<><SectionTitle eyebrow="identidade do usuário" title="Meu perfil"/><div className="profile-grid"><div className="panel profile-card"><div className="profile-avatar">{session.name.split(" ").map(x=>x[0]).slice(0,2).join("")}</div><div><div className="eyebrow">conta autenticada</div><h2>{session.name}</h2><p>@{session.username}</p><Badge tone="green">{session.role}</Badge></div></div><div className="panel profile-card profile-summary"><div><span>contratos registrados</span><strong>{myContracts.length}</strong></div><div><span>pagamentos vinculados</span><strong>{data.payments.filter(p=>p.worker===session.name).length}</strong></div><div><span>ponto registrado</span><strong>{data.punches.filter(p=>p.worker===session.name).length}</strong></div></div></div><ThemePicker/><div className="panel"><SectionTitle eyebrow="seus vínculos" title="Contratos e histórico profissional"/>{myContracts.length?<div className="contract-list">{myContracts.map(c=><div className="contract-card" key={c.id}><div className="contract-id"><code>{c.id}</code><Badge tone={c.status==="Ativo"?"green":"red"}>{c.status}</Badge></div><div className="contract-main"><div><span className="eyebrow">{c.company}</span><h3>{c.role}</h3></div><div className="contract-salary"><strong>{money(c.salary)}</strong><small>{c.schedule}</small></div></div></div>)}</div>:<div className="empty-form">Você ainda não possui contratos registrados.</div>}</div></>} {tab==="dashboard"&&<><div className="hero"><div><div className="eyebrow">painel operacional</div><h1>Painel de trabalho <span>RP</span></h1><p>Olá, {session.name.split(" ")[0]}. Dados dos vínculos profissionais do servidor.</p></div>{canManage&&<button className="primary" onClick={openAdd}><Plus size={17}/> novo registro</button>}</div><div className="notice"><ShieldCheck size={19}/><div><b>Dados protegidos e rastreáveis</b><span>Histórico preservado, permissões por cargo e persistência local. Última sincronização: {now()}.</span></div><button onClick={exportBackup}>exportar backup <Download size={15}/></button></div><div className="stats"><div className="stat"><div className="stat-icon emerald"><UsersRound size={18}/></div><span>TRABALHADORES</span><strong>{data.workers.length}</strong><small><em>{activeContracts.length}</em> contratos ativos</small></div><div className="stat"><div className="stat-icon blue"><FileCheck2 size={18}/></div><span>CONTRATOS ATIVOS</span><strong>{isWorker?myContracts.filter(c=>c.status==="Ativo").length:activeContracts.length}</strong><small><em>{data.contracts.length}</em> no histórico</small></div><div className="stat"><div className="stat-icon gold"><Building2 size={18}/></div><span>EMPRESAS</span><strong>{data.companies.length}</strong><small>{new Set(data.companies.map(c=>c.type)).size} categorias</small></div><div className="stat"><div className="stat-icon purple"><CircleDollarSign size={18}/></div><span>SALÁRIOS PENDENTES</span><strong>{money(pending)}</strong><small className="warning">{data.payments.filter(p=>p.status==="Pendente").length} pagamentos aguardando</small></div></div><div className="grid-2"><div className="panel"><SectionTitle eyebrow="movimentações" title="Atividade recente" action={<button className="ghost" onClick={()=>setTab("reports")}>ver histórico <ChevronRight size={14}/></button>}/><div className="activity-list">{data.audits.slice(0,5).map(a=><div className="activity" key={a.id}><div className={`activity-mark ${a.tone}`}><Check size={14}/></div><div><b>{a.action}</b><span>{a.detail}</span></div><time>{a.when}</time></div>)}</div></div><div className="panel"><SectionTitle eyebrow="atalhos de operação" title="Ações rápidas"/><div className="quick-grid">{canManage&&<><button onClick={()=>{setTab("workers");openAdd()}}><UsersRound size={18}/><b>cadastrar trabalhador</b><span>novo perfil</span></button><button onClick={()=>{setTab("companies");openAdd()}}><Building2 size={18}/><b>cadastrar empresa</b><span>novo estabelecimento</span></button><button onClick={()=>{setTab("contracts");openAdd()}}><FileText size={18}/><b>criar contrato</b><span>formalizar vínculo</span></button></>}<button onClick={()=>setTab("time")}><Clock3 size={18}/><b>registrar ponto</b><span>entrada, intervalo ou saída</span></button></div></div></div></>}
 {tab==="workers"&&<><SectionTitle eyebrow="cadastro de pessoas" title="Trabalhadores" action={canManage&&<button className="primary" onClick={openAdd}><Plus size={17}/> cadastrar trabalhador</button>}/><div className="toolbar"><div className="search"><Search size={16}/><input placeholder="Buscar por nome, ID, profissão ou empresa..." value={query} onChange={e=>setQuery(e.target.value)}/></div><Badge tone="green">{filteredWorkers.length} registros</Badge></div><div className="panel table-panel"><table><thead><tr><th>trabalhador</th><th>ID / telefone</th><th>profissão</th><th>empresa atual</th><th>status</th></tr></thead><tbody>{filteredWorkers.map(w=><tr key={w.id}><td><div className="person"><div className="avatar small">{w.name.split(" ").map(x=>x[0]).slice(0,2).join("")}</div><b>{w.name}</b></div></td><td><code>{w.id}</code><small>{w.phone||"sem telefone"}</small></td><td>{w.profession}</td><td>{w.company}</td><td><Badge tone={w.status==="Ativo"?"green":"neutral"}>{w.status}</Badge>{isAdmin&&<button className="ghost danger-action" onClick={()=>deleteWorker(w)}>excluir</button>}</td></tr>)}</tbody></table></div></>}
 {tab==="companies"&&<><SectionTitle eyebrow="rede de estabelecimentos" title="Empresas" action={canManage&&<button className="primary" onClick={openAdd}><Plus size={17}/> cadastrar empresa</button>}/><div className="company-grid">{data.companies.map(c=>{const employees=data.contracts.filter(x=>x.company===c.name&&x.status==="Ativo").length;return <div className="company-card" key={c.id}><div className="company-top"><div className="company-logo"><Building2 size={20}/></div><Badge tone="gold">{c.type}</Badge></div><h3>{c.name}</h3><p>{c.location||"Localização não informada"}</p><div className="company-meta"><span><UserRound size={14}/> {c.owner}</span><span><UsersRound size={14}/> {employees} funcionários ativos</span></div><button className="ghost full" onClick={()=>{setTab("contracts");setQuery(c.name)}}>ver contratos <ChevronRight size={14}/></button>{isAdmin&&<button className="ghost danger-action full" onClick={()=>deleteCompany(c)}>excluir empresa <X size={14}/></button>}</div>})}</div></>}
 {tab==="contracts"&&<><SectionTitle eyebrow="vínculos profissionais" title={isWorker?"Meus contratos":"Contratos"} action={canManage&&<button className="primary" onClick={openAdd}><Plus size={17}/> criar contrato</button>}/><div className="contract-list">{visibleContracts.map(c=><div className="contract-card" key={c.id}><div className="contract-id"><code>{c.id}</code><Badge tone={c.status==="Ativo"?"green":"red"}>{c.status}</Badge></div><div className="contract-main"><div><span className="eyebrow">{c.company}</span><h3>{c.role}</h3><p><UserRound size={14}/> {c.worker}</p></div><div className="contract-salary"><span>salário mensal</span><strong>{money(c.salary)}</strong><small>{c.schedule}</small></div></div><div className="contract-footer"><span><CalendarClock size={14}/> admissão {c.admitted}</span><span className={c.workerSigned?"signed":"pending-sign"}>{c.workerSigned?<Check size={14}/>:<X size={14}/>} trabalhador</span><span className={c.employerSigned?"signed":"pending-sign"}>{c.employerSigned?<Check size={14}/>:<X size={14}/>} empregador</span>{c.status==="Ativo"&&<><button className="ghost" onClick={()=>signContract(c)}>assinar <Check size={14}/></button>{canManage&&<><button className="ghost" onClick={()=>editContract(c)}>editar <Settings2 size={14}/></button><button className="ghost" onClick={()=>createPayment(c)}>gerar salário <CircleDollarSign size={14}/></button><button className="ghost danger-action" onClick={()=>closeContract(c)}>encerrar <X size={14}/></button></>}</>}{c.status==="Encerrado"&&<><span className="pending-sign">encerramento {money(c.closingAmount||0)}</span><button className="ghost" onClick={()=>signTermination(c)}>assinar encerramento <Check size={14}/></button></>}<button className="ghost" onClick={()=>printReport(`Contrato de trabalho ${c.id}`,`<h2>CONTRATO DE TRABALHO — RPG</h2><h3>1. DADOS DO EMPREGADOR</h3><p>Empresa: ${esc(c.company)}<br>Responsável: ${esc(data.companies.find(x=>x.name===c.company)?.owner||session.name)}</p><h3>2. DADOS DO TRABALHADOR</h3><p>Nome: ${esc(c.worker)}<br>ID: ${esc(data.workers.find(x=>x.name===c.worker)?.id||"—")}<br>Telefone: ${esc(data.workers.find(x=>x.name===c.worker)?.phone||"—")}</p><h3>3. INFORMAÇÕES DO CONTRATO</h3><p>Cargo: ${esc(c.role)}<br>Salário: ${money(c.salary)}<br>Jornada: ${esc(c.schedule)}<br>Admissão: ${esc(c.admitted)}<br>Tipo: ${esc(c.contractType||"Prazo indeterminado")}<br>Benefícios: ${esc(c.benefits||"Não informado")}</p><h3>4. OBRIGAÇÕES</h3><p>O trabalhador cumprirá horários, respeitará as regras da empresa e exercerá suas funções com responsabilidade. O empregador realizará os pagamentos e manterá os registros de jornada.</p><h3>5. ASSINATURAS</h3><p>Empregador: ${c.employerSigned?"✓ assinado":"__________________"}<br>Trabalhador: ${c.workerSigned?"✓ assinado":"__________________"}</p><h3>6. ENCERRAMENTO</h3><p>O contrato poderá ser encerrado conforme as regras do servidor RPG.</p><p><b>Status:</b> ${c.status}</p><small>Documento destinado exclusivamente ao uso em RPG, sem validade como contrato de trabalho real.</small>`)}><FileText size={14}/> PDF</button><button className="ghost" onClick={()=>shareContract(c)}><Link2 size={14}/> link para assinar</button>{isAdmin&&<button className="ghost danger-action" onClick={()=>deleteContract(c)}>excluir <X size={14}/></button>}</div></div>)}{!visibleContracts.length&&<div className="panel empty-form">Nenhum contrato encontrado para este usuário.</div>}</div></>}
 {tab==="signed"&&<><SectionTitle eyebrow="documentos recebidos" title="Contratos assinados" action={<Badge tone="green">{signedContracts.length} documentos</Badge>}/><div className="panel signed-contract-intro"><FileCheck2 size={22}/><div><b>Assinaturas recebidas</b><span>Os contratos abaixo foram assinados digitalmente pelo trabalhador e recebidos pela carteira.</span></div></div><div className="contract-list">{signedContracts.map(c=><div className="contract-card" key={c.id}><div className="contract-id"><code>{c.id}</code><Badge tone="green">assinado</Badge></div><div className="contract-main"><div><span className="eyebrow">{c.company}</span><h3>{c.role}</h3><p><UserRound size={14}/> {c.worker}</p></div><div className="contract-salary"><strong>{money(c.salary)}</strong><small>{c.schedule}</small></div></div><div className="contract-footer"><span><Check size={14}/> trabalhador assinou</span><span>{c.signedAt?new Date(c.signedAt).toLocaleDateString("pt-BR"):"recebido agora"}</span><button className="ghost" onClick={()=>printReport(`Contrato assinado ${c.id}`,`<h2>CONTRATO DE TRABALHO — RPG</h2><p><b>Trabalhador:</b> ${esc(c.worker)}<br><b>Empresa:</b> ${esc(c.company)}<br><b>Cargo:</b> ${esc(c.role)}<br><b>Salário:</b> ${money(c.salary)}<br><b>Benefícios:</b> ${esc(c.benefits||"Não informado")}</p><h3>Assinaturas</h3><p>Trabalhador: ✓ assinado<br>Empregador: ${c.employerSigned?"✓ assinado":"pendente"}</p>`)}>visualizar PDF <FileText size={14}/></button></div></div>)}{!signedContracts.length&&<div className="panel empty-form">Nenhum contrato assinado foi recebido ainda.</div>}</div></>}
 {tab==="time"&&<><SectionTitle eyebrow="jornada e presença" title="Controle de ponto" action={<div style={{display:"flex",gap:8}}>{(isAdmin||isEmployer)&&<select value={selectedPunchWorker} onChange={e=>setSelectedPunchWorker(e.target.value)}><option value="">selecionar trabalhador</option>{data.workers.map(w=><option key={w.id}>{w.name}</option>)}</select>}<button className="primary" onClick={()=>recordPunch(selectedPunchWorker||session.name)}><Clock3 size={17}/> registrar batida</button></div>}/><div className="time-banner"><div><span className="eyebrow">jornada em andamento</span><h3>{selectedPunchWorker||session.name} <Badge tone="green">ao vivo</Badge></h3><p>As batidas seguem a sequência: entrada → início/fim de intervalo → saída.</p></div><div className="live-time">{now()}<small>horário do servidor</small></div></div><div className="panel table-panel"><SectionTitle eyebrow="últimos registros" title="Histórico de ponto"/><table><thead><tr><th>trabalhador</th><th>data</th><th>entrada</th><th>intervalo</th><th>saída</th><th>horas</th></tr></thead><tbody>{data.punches.filter(p=>isWorker?p.worker===session.name:true).map(p=><tr key={p.id}><td><b>{p.worker}</b></td><td>{p.date}</td><td><Badge tone="green">{p.entry||"—"}</Badge></td><td>{p.breakStart||"—"} {p.breakEnd&&`→ ${p.breakEnd}`}</td><td>{p.exit||"em aberto"}</td><td><code>{hoursFor(p).toFixed(2)}h</code>{isAdmin&&<button className="ghost danger-action" onClick={()=>deletePunch(p)}>excluir</button>}</td></tr>)}</tbody></table></div></>}
 {tab==="payroll"&&<><SectionTitle eyebrow="folha e pagamentos" title="Salários" action={canManage&&<button className="primary" onClick={()=>{const p=data.payments.find(x=>x.status==="Pendente");if(p)registerPayment(p);else toast.info("Não há pagamentos pendentes")}}><Plus size={17}/> registrar pagamento</button>}/><div className="payroll-summary"><div><span>total pago</span><strong>{money(totalPaid)}</strong><small>valores líquidos recebidos</small></div><div><span>aguardando pagamento</span><strong className="gold-text">{money(pending)}</strong><small>{data.payments.filter(p=>p.status==="Pendente").length} pendências</small></div><div><span>descontos aplicados</span><strong>{money(data.payments.reduce((s,p)=>s+p.discount,0))}</strong><small>neste histórico</small></div></div><div className="panel table-panel"><SectionTitle eyebrow="histórico financeiro" title="Pagamentos, descontos e datas"/><table><thead><tr><th>trabalhador</th><th>empresa</th><th>referência</th><th>bruto / desconto</th><th>líquido</th><th>data</th><th>status</th></tr></thead><tbody>{data.payments.filter(p=>isWorker?p.worker===session.name:true).map(p=><tr key={p.id}><td><b>{p.worker}</b></td><td>{p.company}</td><td>{p.reference}</td><td>{money(p.amount)}<small className="discount">desconto {money(p.discount)}</small></td><td><strong>{money(p.amount-p.discount)}</strong></td><td>{p.date}</td><td><Badge tone={p.status==="Pago"?"green":"gold"}>{p.status}</Badge>{p.status==="Pendente"&&canManage&&<button className="pay-action" onClick={()=>registerPayment(p)}>pagar agora</button>}{isAdmin&&<button className="ghost danger-action" onClick={()=>deletePayment(p)}>excluir</button>}</td></tr>)}</tbody></table></div></>}
 {tab==="settings"&&isAdmin&&<><SectionTitle eyebrow="admin master" title="Contas e permissões" action={<button className="primary" onClick={()=>{const name=window.prompt("Nome do usuário:");const username=window.prompt("Username:");const password=window.prompt("Senha inicial:");const role=window.prompt("Cargo (Admin Master, Empregador ou Trabalhador):","Empregador") as Role|null;if(name&&username&&password&&role&&["Admin Master","Empregador","Trabalhador"].includes(role)){if(accounts.some(a=>a.username===username))return toast.error("Username já cadastrado");setAccounts(a=>[...a,{id:`ACC-${Date.now()}`,name,username,role,password,active:true}]);pushAudit("Conta criada",`${name} • ${role}`);toast.success("Conta criada")}}}><Plus size={17}/> criar usuário e senha</button>}/><div className="panel table-panel"><table><thead><tr><th>nome</th><th>username</th><th>cargo</th><th>status</th><th>ação</th></tr></thead><tbody>{accounts.map(a=><tr key={a.id}><td><b>{a.name}</b></td><td><code>{a.username}</code></td><td>{a.role}</td><td><Badge tone={a.active?"green":"red"}>{a.active?"Ativa":"Bloqueada"}</Badge></td><td>{a.username!=="master"&&<><button className="ghost" onClick={()=>setAccounts(list=>list.map(x=>x.id===a.id?{...x,active:!x.active}:x))}>{a.active?"bloquear":"ativar"}</button><button className="ghost danger-action" onClick={()=>deleteAccount(a)}>excluir</button></>}</td></tr>)}</tbody></table></div><div className="notice"><ShieldCheck size={19}/><div><b>Admin Master tem acesso total</b><span>Admin cria contas, bloqueia usuários, gerencia trabalhadores, empresas, contratos, pagamentos, ponto e relatórios.</span></div></div></>}
 {tab==="reports"&&<><SectionTitle eyebrow="dados e auditoria" title="Relatórios" action={<button className="primary" onClick={reportWorkers}><FileText size={17}/> PDF funcionários</button>}/><div className="report-grid"><div className="report-card"><BarChart3/><b>Funcionários e vínculos</b><span>Lista de trabalhadores, profissões, empresas e status.</span><button onClick={reportWorkers}>gerar relatório <ChevronRight size={14}/></button></div><div className="report-card"><CircleDollarSign/><b>Salários e despesas</b><span>Pagamentos, pendências, descontos e valores líquidos.</span><button onClick={reportPayroll}>gerar relatório <ChevronRight size={14}/></button></div><div className="report-card"><Clock3/><b>Horas trabalhadas</b><span>Entradas, intervalos, saídas e totais calculados.</span><button onClick={reportHours}>gerar relatório <ChevronRight size={14}/></button></div></div><div className="panel"><SectionTitle eyebrow="log de modificações" title="Histórico do sistema"/><div className="audit-list">{data.audits.map(a=><div className="audit-row" key={a.id}><div className={`activity-mark ${a.tone}`}><History size={14}/></div><div><b>{a.action}</b><span>{a.detail}</span></div><time>{a.when}</time></div>)}</div></div></>}
 </div></main>{showAdd&&<div className="modal-backdrop" onClick={()=>setShowAdd(false)}><div className="modal" onClick={e=>e.stopPropagation()}><div className="modal-head"><div><div className="eyebrow">novo registro</div><h2>{tab==="workers"?"Cadastrar trabalhador":tab==="companies"?"Cadastrar empresa":tab==="contracts"?"Criar contrato":"Adicionar registro"}</h2></div><button className="icon-button" onClick={()=>setShowAdd(false)}><X size={18}/></button></div>{tab==="workers"&&<div className="form-grid"><Field label="Nome completo"><input autoFocus value={workerForm.name} onChange={e=>setWorkerForm({...workerForm,name:e.target.value})} placeholder="Ex.: Alex Morgan"/></Field><Field label="ID do trabalhador"><input value={workerForm.id} onChange={e=>setWorkerForm({...workerForm,id:e.target.value})} placeholder="RPG-004"/></Field><Field label="Telefone"><input value={workerForm.phone} onChange={e=>setWorkerForm({...workerForm,phone:e.target.value})} placeholder="(00) 00000-0000"/></Field><Field label="Profissão"><input value={workerForm.profession} onChange={e=>setWorkerForm({...workerForm,profession:e.target.value})} placeholder="Ex.: Segurança"/></Field><Field label="Usuário de login"><input autoComplete="username" value={workerForm.username} onChange={e=>setWorkerForm({...workerForm,username:e.target.value})} placeholder="ex.: joao.silva"/></Field><Field label="Senha"><input type="password" autoComplete="new-password" value={workerForm.password} onChange={e=>setWorkerForm({...workerForm,password:e.target.value})} placeholder="mínimo de 4 caracteres"/></Field><Field label="Confirmar senha"><input type="password" autoComplete="new-password" value={workerForm.passwordConfirm} onChange={e=>setWorkerForm({...workerForm,passwordConfirm:e.target.value})} placeholder="repita a senha"/></Field><div className="credential-hint">Esse usuário poderá entrar na carteira usando a senha definida pelo Admin Master.</div><button className="primary form-submit" onClick={addWorker}>salvar trabalhador e acesso <Check size={16}/></button></div>}{tab==="companies"&&<div className="form-grid"><Field label="Nome da empresa"><input autoFocus value={companyForm.name} onChange={e=>setCompanyForm({...companyForm,name:e.target.value})} placeholder="Ex.: Loja Pixel"/></Field><Field label="Tipo de negócio"><select value={companyForm.type} onChange={e=>setCompanyForm({...companyForm,type:e.target.value})}><option>Bar</option><option>Loja</option><option>Restaurante</option><option>Hospital</option><option>Oficina</option><option>Segurança</option><option>Outro</option></select></Field><Field label="Responsável"><input value={companyForm.owner} onChange={e=>setCompanyForm({...companyForm,owner:e.target.value})} placeholder="Nome do responsável"/></Field><Field label="Localização"><input value={companyForm.location} onChange={e=>setCompanyForm({...companyForm,location:e.target.value})} placeholder="Bairro • Cidade"/></Field><button className="primary form-submit" onClick={addCompany}>salvar empresa <Check size={16}/></button></div>}{tab==="contracts"&&<div className="form-grid"><Field label="Trabalhador"><select value={contractForm.worker} onChange={e=>setContractForm({...contractForm,worker:e.target.value})}>{data.workers.map(w=><option key={w.id}>{w.name}</option>)}</select></Field><Field label="Empresa"><select value={contractForm.company} onChange={e=>setContractForm({...contractForm,company:e.target.value})}>{data.companies.map(c=><option key={c.id}>{c.name}</option>)}</select></Field><Field label="Cargo"><input autoFocus value={contractForm.role} onChange={e=>setContractForm({...contractForm,role:e.target.value})} placeholder="Ex.: Gerente"/></Field><Field label="Salário mensal (R$)"><input type="number" min="0" value={contractForm.salary} onChange={e=>setContractForm({...contractForm,salary:e.target.value})} placeholder="5000"/></Field><Field label="Horário"><input value={contractForm.schedule} onChange={e=>setContractForm({...contractForm,schedule:e.target.value})} placeholder="08:00 — 16:00"/></Field><Field label="Data de admissão"><input type="date" value={contractForm.admitted} onChange={e=>setContractForm({...contractForm,admitted:e.target.value})}/></Field><Field label="Tipo de contrato"><select value={contractForm.contractType} onChange={e=>setContractForm({...contractForm,contractType:e.target.value})}><option>Prazo indeterminado</option><option>Prazo determinado</option><option>Experiência</option></select></Field><Field label="Benefícios (vale alimentação, transporte etc.)"><input value={contractForm.benefits} onChange={e=>setContractForm({...contractForm,benefits:e.target.value})} placeholder="Vale alimentação; Vale transporte"/></Field><button className="primary form-submit" onClick={addContract}>criar e enviar para assinatura <FileCheck2 size={16}/></button></div>}</div></div>}</div>;
}

export default function Home(){const params=new URLSearchParams(window.location.search);const sign=params.get("signContract");if(sign){try{return <ContractSigningScreen payload={decodeLinkData(sign)}/>}catch{return <div className="login-screen"><div className="modal"><h2>Link de contrato inválido</h2><p>Solicite um novo link ao responsável.</p></div></div>}}return <Workspace/>}
